import json
F='/home/claude/ac-mdcu/parts/fill/l05_r03.json'
D=json.load(open(F))
def S(n,**kw):
    q=D[str(n)]
    for k,v in kw.items():
        if k=='wrong':
            q['wrong'].update(v)
        else:
            q[k]=v

# ---------- 21 ----------
S(21,
why='Dog ear (standing cone) เกิดเมื่อเย็บปิดแผลที่สั้นเกินเทียบกับความกว้าง (แผลกระสวยควรยาว:กว้างราว 3:1 มุมปลายราว 30°) ผิวส่วนเกินจึงนูนเป็นกรวยที่ปลายหรือที่มุมแผล · กรวยที่อยู่<b>ตรงมุมหักของแผล</b> (รูป I) ยืดตรงไม่ได้ เพราะแนวแผลสองข้างของมุมชี้คนละทิศ ถ้ายืดตามแกนใดแกนหนึ่ง กรวยจะย้ายตำแหน่งแต่ไม่หาย → ยกกรวยขึ้นด้วย hook แล้วกรีด (J) จากนั้น<b>ตัดผิวส่วนเกินเป็นสามเหลี่ยมออกไปด้านข้างในแนวตั้งฉาก</b> (K) ได้แผลรูปตัว L มุมฉาก (L) โดยแผลยาวขึ้นเพียงเล็กน้อย · ต่างจากกรวยที่ปลายแผลตรง ซึ่งใช้วิธียืดตรง (A–D) หรือกรีดข้างเดียวแล้วแผ่ผิวทับ (E–H) · ที่ไหล่ซึ่งแรงตึงสูง ควรวางขาใหม่ของแผลให้ใกล้แนว RSTL และเย็บชั้น dermis รับแรงก่อนประกบผิว · สไลด์หน้า 8 ลายมือ <b>"② Dog ear ตรงจุดที่มีการหักมุม = ตัดเป็นมุมฉากออกด้านข้าง"</b>',
wrong={'C':'ผ้ากดช่วยลดเลือดออกและบวมใต้แผล แต่ไม่ได้เอาผิวส่วนเกินออก กรวยที่เกิดจากผิวเกินจริงจะคงอยู่หรือยุบลงเพียงบางส่วน · ไม่มีสถานการณ์ใดที่ผ้ากดแก้กรวยผิวเกินตรงมุมแผลได้ เพราะปัญหาคือปริมาตรผิวที่เกิน ไม่ใช่บวมหรือเลือดคั่ง'})

D['21']['summary']=[x.replace('(in case < 1:3)','(in case &lt; 1:3)') for x in D['21']['summary']]

